      'A unit-radius sector of angle x has area (1/2)r²θ = x/2. It is squeezed between the two triangles.');
    angleMark(panelsG, vB, y0, x, 30);
    mathText(panelsG, '1', vB[0] + S / 2 - 4, y0 + 8, 16);
    mathText(panelsG, 'Area of sector', vB[0] - 2, y0 + 40, 15, 'start', '#000').font({ style: 'normal' });
    mathText(panelsG, 'x / 2', vB[0] + 42, y0 + 62, 16);

    // Panel C: inner triangle, base cos x, height sin x
    var baseC = vC[0] + S * c, apexC = [baseC, y0 - S * s];
    var triC = panelsG.polygon([vC.join(','), baseC + ',' + y0, apexC.join(',')].join(' '))
      .fill(PEACH).stroke({ color: RED, width: 2 });
    addClick(triC, 'Inner triangle — area sin x / 2',
      'With vertices (0,0), (cos x, 0) and (cos x, sin x) — base cos x times height sin x over 2 — its area sin x cos x/2 ≤ sin x/2. It is the smallest of the three regions.');
    panelsG.line(apexC[0], apexC[1], baseC, y0).stroke({ color: RED, width: 1.5, dasharray: '5,4' });
    // dashed blue arc
    var arcC = [];
    for (var k = 0; k <= 30; k++) { var a3 = x * k / 30; arcC.push((vC[0] + S * Math.cos(a3)) + ',' + (y0 - S * Math.sin(a3))); }
    panelsG.polyline(arcC.join(' ')).fill('none').stroke({ color: BLUE, width: 2.5, dasharray: '7,6' });
    angleMark(panelsG, vC, y0, x, 30);
    mathText(panelsG, '1', vC[0] + S / 2 - 4, y0 + 8, 16);
    mathText(panelsG, 'sin x', baseC + 6, apexC[1] + (y0 - apexC[1]) / 2 - 8, 15);
    mathText(panelsG, 'Area of triangle', vC[0] - 6, y0 + 40, 15, 'start', '#000').font({ style: 'normal' });
    mathText(panelsG, 'sin x / 2', vC[0] + 28, y0 + 62, 16);

    // inequality symbols between panels
    mathText(panelsG, '≥', 672, y0 - 30, 24, 'middle', '#000').font({ style: 'normal' });
    mathText(panelsG, '≥', 828, y0 - 30, 24, 'middle', '#000').font({ style: 'normal' });
    mathText(panelsG, '≥', 668, y0 + 60, 24, 'middle', '#000').font({ style: 'normal' });
    mathText(panelsG, '≥', 824, y0 + 60, 24, 'middle', '#000').font({ style: 'normal' });
  } else {
    // ---- nested overlay: one shared vertex ----
    var V = [640, 420], S2 = 240, y2 = V[1];
    // big triangle
    var big = overlayG.polygon([V.join(','), (V[0] + S2) + ',' + y2, (V[0] + S2) + ',' + (y2 - S2 * t)].join(' '))
      .fill(PEACH).stroke({ color: RED, width: 2 });
    addClick(big, 'Outer triangle — area tan x / 2',
      'Largest region: base 1, height tan x, area tan x/2. The sector lies entirely inside it.');
    // sector
    var sp = [V.join(',')];
    for (var i = 0; i <= 40; i++) { var a = x * i / 40; sp.push((V[0] + S2 * Math.cos(a)) + ',' + (y2 - S2 * Math.sin(a))); }
    var secO = overlayG.polygon(sp.join(' ')).fill('#f4c9b0').stroke({ color: RED, width: 1.5 });
    overlayG.polyline(sp.slice(1).join(' ')).fill('none').stroke({ color: BLUE, width: 3 });
    addClick(secO, 'Sector — area x / 2',
      'Middle region: unit sector of angle x, area x/2. It contains the inner triangle and is contained in the outer triangle.');
    // inner triangle
    var bX = V[0] + S2 * c, apY = y2 - S2 * s;
    var triO = overlayG.polygon([V.join(','), bX + ',' + y2, bX + ',' + apY].join(' '))
      .fill('#efab8a').stroke({ color: RED, width: 1.5 });
    addClick(triO, 'Inner triangle — area sin x / 2',
      'Smallest region: height sin x, area sin x/2 (up to the cos x factor). The nesting gives sin x ≤ x ≤ tan x.');
    overlayG.line(bX, apY, bX, y2).stroke({ color: RED, width: 1.4, dasharray: '5,4' });
    angleMark(overlayG, V, y2, x, 44);
    // labels with leaders
    mathText(overlayG, 'tan x', V[0] + S2 + 8, y2 - S2 * t / 2 - 8, 17);
    mathText(overlayG, 'x  (sector arc)', V[0] + S2 * 1.02, y2 - S2 * Math.sin(x / 2) - 20, 16);
    mathText(overlayG, 'sin x', bX + 6, apY - 6, 16);
    mathText(overlayG, '1', V[0] + S2 / 2 - 4, y2 + 8, 17);
    mathText(overlayG, 'sin x ≤ x ≤ tan x', V[0] + 30, 462, 22, 'start', '#000').font({ style: 'italic' });
  }
}

function angleMark(g, V, y0, x, r) {
  var pts = [];
  for (var i = 0; i <= 16; i++) { var a = x * i / 16; pts.push((V[0] + r * Math.cos(a)) + ',' + (y0 - r * Math.sin(a))); }
  g.polyline(pts.join(' ')).fill('none').stroke({ color: '#333', width: 1.2 });
  mathText(g, 'x', V[0] + r + 5, y0 - 16, 15);
}

function update_angleX(v) { state.x = v; redraw(); }
function toggle_viewMode(on) { state.overlay = on; redraw(); }

// ---------- demo step player ----------
var steps = [
  { title: 'Meet the three regions',
    narration: 'On the unit circle, angle x defines three nested shapes: a small triangle of height sin x, a circular sector, and a large triangle of height tan x. Each panel shows one shape and its area formula.',
    state: { angleX: 0.6, overlay: false } },
  { title: 'Containment gives the inequality',
    narration: 'Nested overlay: the small triangle lies inside the sector and the sector inside the big triangle, so sin x/2 ≤ x/2 ≤ tan x/2.',
    state: { angleX: 0.6, overlay: true } },
  { title: 'Squeeze toward x = 0',
    narration: 'As x → 0 all three shaded areas shrink together and become nearly identical — sin x / x is trapped between cos x and 1/cos x, both tending to 1. The limit is 1.',
    state: { angleX: 0.1, overlay: true } }
];
var stepIdx = 0;
function applyStep(i) {
  stepIdx = Math.max(0, Math.min(steps.length - 1, i));
  var st = steps[stepIdx];
  document.getElementById('angleXInput').value = st.state.angleX;
  document.getElementById('angleXVal').value = st.state.angleX.toFixed(2);
  document.getElementById('viewModeInput').checked = st.state.overlay;
  state.x = st.state.angleX; state.overlay = st.state.overlay;
  document.getElementById('demoNarration').textContent = (stepIdx + 1) + '. ' + st.title + ' — ' + st.narration;
  document.getElementById('stepLabel').textContent = (stepIdx + 1) + ' / ' + steps.length;
  redraw();
}
function nextStep() { applyStep(stepIdx + 1); }
function prevStep() { applyStep(stepIdx - 1); }

applyStep(0);
window.__markRendered();
// @FIGURE_CODE_END

Fix all identified failure modes and improve every score. Maintain or improve what already works well.
Return ONLY the updated marker-wrapped payload.

userContent.text:
Build an interactive figure using SVG.js.

CONCEPT: Comparing the areas of an outer triangle, a circular sector, and an inner triangle on the unit circle yields the inequality sin x ≤ x ≤ tan x, which the Squeezing Theorem turns into lim(x→0) sin x / x = 1.
KEY INSIGHT (what students should walk away understanding): The geometric containment triangle ⊃ sector ⊃ triangle gives sin x ≤ x ≤ tan x for all small x, and since all three areas converge as x → 0, the Squeezing Theorem forces sin x / x → 1.
DEMO STEPS: 3 guided steps — implement the step player in #ui

FULL BLUEPRINT:
